content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-blue: #38bdf8;
  --accent-blue-hover: #0ea5e9;
  --accent-glow: rgba(56, 189, 248, 0.35);
  --border-color: rgba(255, 255, 255, 0.1);
  --border-focus: rgba(56, 189, 248, 0.6);
  --card-bg: rgba(30, 41, 59, 0.85);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.45);
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  min-height: 100dvh;
  overflow-x: hidden;
}

/* アクセシビリティ用フォーカススタイル */
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* アプリ全体コンテナ */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
  width: 100%;
  background: radial-gradient(circle at 50% 20%, #1e293b 0%, #0f172a 100%);
}

/* ヘッダー */
.app-header {
  padding: 1.25rem 2rem;
  border-bottom: 1px solid var(--border-color);
  background: rgba(15, 23, 42, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  z-index: 10;
}

.header-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* メインレイアウト */
.main-layout {
  flex: 1;
  display: flex;
  flex-direction: row;
  position: relative;
  overflow: hidden;
  min-height: calc(100vh - 80px);
  min-height: calc(100dvh - 80px);
}

/* 3Dキャンバスコンテナ */
.canvas-container {
  position: relative;
  flex: 1;
  display: flex;
}

/* 3Dキャンバス領域 */
.canvas-wrapper {
  flex: 1;
  position: relative;
  min-height: 400px;
  background-color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.three-canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
  outline: none;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}

.three-canvas:active {
  cursor: grabbing;
}

/* 操作ヒント */
.hint-box {
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.6rem 1rem;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.6rem;
  pointer-events: none;
  box-shadow: var(--shadow-md);
  z-index: 5;
  user-select: none;
  -webkit-user-select: none;
}

.hint-icon {
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-blue);
}

.hint-text {
  font-size: 0.8125rem;
  color: var(--text-muted);
  letter-spacing: 0.01em;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.kbd-badge {
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-main);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.1rem 0.4rem;
  font-size: 0.75rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* コントロールパネル */
.control-panel {
  width: 340px;
  max-width: 100%;
  background: var(--card-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-left: 1px solid var(--border-color);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
  z-index: 10;
}

.panel-section {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem;
  box-shadow: var(--shadow-sm);
}

.section-title {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent-blue);
  user-select: none;
  -webkit-user-select: none;
}

.control-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.control-label {
  font-size: 0.875rem;
  color: var(--text-main);
  font-weight: 500;
}

/* カラーパレット */
.color-palette {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0.5rem;
  width: 100%;
}

.color-btn {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  cursor: pointer;
  outline: none;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  position: relative;
  user-select: none;
  -webkit-user-select: none;
}

.color-btn:hover {
  transform: scale(1.1);
  box-shadow: var(--shadow-md);
}

.color-btn:active {
  transform: scale(0.95);
}

.color-btn-active {
  border-color: #ffffff;
  box-shadow: 0 0 12px var(--accent-glow);
  transform: scale(1.08);
}

/* トグルボタン */
.toggle-btn {
  background: var(--bg-tertiary);
  color: var(--text-muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 0.45rem 0.9rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  text-align: center;
  white-space: nowrap;
  user-select: none;
  -webkit-user-select: none;
}

.toggle-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-main);
  box-shadow: var(--shadow-sm);
}

.toggle-btn-active {
  background: var(--accent-blue);
  color: #0f172a;
  border-color: var(--accent-blue);
  box-shadow: 0 0 12px var(--accent-glow);
}

.toggle-btn-active:hover {
  background: var(--accent-blue-hover);
  color: #0f172a;
}

/* スライダー */
.range-slider {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  background: var(--bg-tertiary);
  border-radius: 3px;
  outline: none;
  cursor: pointer;
  transition: background 0.2s;
}

.range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-blue);
  cursor: pointer;
  box-shadow: 0 0 8px var(--accent-glow);
  transition: transform 0.15s ease;
}

.range-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 50%;
  background: var(--accent-blue);
  cursor: pointer;
  box-shadow: 0 0 8px var(--accent-glow);
  transition: transform 0.15s ease;
}

.range-slider:active::-webkit-slider-thumb {
  transform: scale(1.2);
}

.range-slider:active::-moz-range-thumb {
  transform: scale(1.2);
}

.range-value {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent-blue);
  min-width: 2.5rem;
  text-align: right;
  font-variant-numeric: tabular-nums;
  user-select: none;
  -webkit-user-select: none;
}

/* リセットボタン */
.reset-btn {
  width: 100%;
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
  border-radius: var(--radius-md);
  padding: 0.75rem 1rem;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  outline: none;
  margin-top: auto;
  user-select: none;
  -webkit-user-select: none;
}

.reset-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  border-color: rgba(239, 68, 68, 0.5);
  color: #ffffff;
  box-shadow: 0 0 12px rgba(239, 68, 68, 0.25);
}

.reset-btn:active {
  transform: scale(0.98);
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .main-layout {
    flex-direction: column;
    min-height: auto;
    height: auto;
  }

  .canvas-wrapper {
    flex: none;
    height: 48dvh;
    min-height: 280px;
  }

  .control-panel {
    width: 100%;
    flex: 1 1 auto;
    border-left: none;
    border-top: 1px solid var(--border-color);
    padding: 1.25rem 1rem;
    max-height: none;
  }

  .app-header {
    padding: 1rem;
  }

  .hint-box {
    bottom: 0.75rem;
    left: 0.75rem;
    padding: 0.4rem 0.75rem;
  }

  .hint-text {
    font-size: 0.75rem;
  }
}

import type { RefObject } from 'react';

/**
 * 3D立方体のレンダリングおよびアニメーション設定
 */
export interface CubeConfig {
  /** 立方体のマテリアルカラー (HEXカラーコード形式、例: '#38bdf8') */
  color: string;
  /** ワイヤーフレーム表示の有効/無効 (true: 線画表示、false: 面表示) */
  wireframe: boolean;
  /** 自動回転アニメーションの有効/無効 */
  autoRotate: boolean;
  /** 自動回転速度 (許容範囲: 0.1 〜 3.0、標準値: 1.0) */
  rotateSpeed: number;
  /** マテリアルの質感設定 (true: 光沢メタリック、false: マット) */
  metallic: boolean;
}

/**
 * 立方体設定の部分更新用パラメータ型
 */
export type CubeConfigUpdate = Partial<CubeConfig>;

/**
 * 操作コントロールパネルのProps
 */
export interface ControlPanelProps {
  /** 現在の立方体設定値 */
  config: CubeConfig;
  /** 設定更新コールバック関数 */
  onChangeConfig: (newConfig: CubeConfigUpdate) => void;
  /** 視点（カメラ角度・ズーム）を初期状態へ戻すコールバック関数 */
  onResetView: () => void;
}

/**
 * Three.jsキャンバス表示コンポーネントのProps
 */
export interface ThreeCanvasProps {
  /** 現在の立方体設定値 */
  config: CubeConfig;
  /** 視点リセット関数を親コンポーネントに公開するためのRefオブジェクト */
  resetViewRef?: RefObject<(() => void) | null>;
}

import { useEffect, useRef, useImperativeHandle, forwardRef, useCallback } from 'react';
import * as THREE from 'three';
import { ThreeCanvasProps } from '../types';

export interface ThreeCanvasHandle {
  resetView: () => void;
}

const INITIAL_CAMERA_DISTANCE = 5;
const INITIAL_ROTATION_X = 0.35;
const INITIAL_ROTATION_Y = 0.55;

const ThreeCanvas = forwardRef<ThreeCanvasHandle, ThreeCanvasProps>(
  ({ config, resetViewRef }, ref) => {
    const mountRef = useRef<HTMLDivElement | null>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);

    // Three.js インスタンスの参照保持
    const cubeMeshRef = useRef<THREE.Mesh | null>(null);
    const materialRef = useRef<THREE.MeshStandardMaterial | null>(null);
    const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
    const sceneRef = useRef<THREE.Scene | null>(null);
    const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

    // インタラクション操作用の状態参照
    const isDraggingRef = useRef(false);
    const previousPointerPositionRef = useRef({ x: 0, y: 0 });
    const rotationAnglesRef = useRef({ x: INITIAL_ROTATION_X, y: INITIAL_ROTATION_Y });
    const cameraDistanceRef = useRef(INITIAL_CAMERA_DISTANCE);
    const reqIdRef = useRef<number | null>(null);
    const configRef = useRef(config);

    // マルチタッチ・ピンチ操作用
    const activePointersRef = useRef<Map<number, { x: number; y: number }>>(new Map());
    const initialPinchDistanceRef = useRef<number | null>(null);
    const initialCameraDistanceRef = useRef<number>(INITIAL_CAMERA_DISTANCE);

    // カメラ位置を球面座標から再計算
    const updateCameraPosition = useCallback(() => {
      if (!cameraRef.current) return;
      const { x, y } = rotationAnglesRef.current;
      const distance = cameraDistanceRef.current;

      cameraRef.current.position.x = distance * Math.cos(x) * Math.sin(y);
      cameraRef.current.position.y = distance * Math.sin(x);
      cameraRef.current.position.z = distance * Math.cos(x) * Math.cos(y);
      cameraRef.current.lookAt(0, 0, 0);
    }, []);

    // 視点リセット関数
    const handleReset = useCallback(() => {
      rotationAnglesRef.current = { x: INITIAL_ROTATION_X, y: INITIAL_ROTATION_Y };
      cameraDistanceRef.current = INITIAL_CAMERA_DISTANCE;
      if (cubeMeshRef.current) {
        cubeMeshRef.current.rotation.set(0, 0, 0);
      }
      updateCameraPosition();
    }, [updateCameraPosition]);

    // useImperativeHandle による resetView の公開
    // 関数としても呼び出し可能にして props.resetViewRef と ref の両互換性を維持
    useImperativeHandle(
      ref,
      () => {
        const handler = () => handleReset();
        handler.resetView = handleReset;
        return handler as unknown as ThreeCanvasHandle;
      },
      [handleReset]
    );

    useImperativeHandle(
      resetViewRef,
      () => {
        const handler = () => handleReset();
        handler.resetView = handleReset;
        return handler as unknown as (() => void);
      },
      [handleReset]
    );

    // configの最新値をrefとマテリアルに同期
    useEffect(() => {
      configRef.current = config;
      if (materialRef.current) {
        materialRef.current.color.set(config.color);
        materialRef.current.wireframe = config.wireframe;
        materialRef.current.metalness = config.metallic ? 0.85 : 0.1;
        materialRef.current.roughness = config.metallic ? 0.2 : 0.65;
        materialRef.current.needsUpdate = true;
      }
    }, [config]);

    useEffect(() => {
      const container = mountRef.current;
      const canvas = canvasRef.current;
      if (!container || !canvas) return;

      // シーンの作成
      const scene = new THREE.Scene();
      sceneRef.current = scene;

      // カメラの作成
      const width = container.clientWidth || 600;
      const height = container.clientHeight || 400;
      const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
      cameraRef.current = camera;
      updateCameraPosition();

      // レンダラーの作成
      const renderer = new THREE.WebGLRenderer({
        canvas,
        antialias: true,
        alpha: true,
        powerPreference: 'high-performance',
      });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(width, height);
      renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap;
      rendererRef.current = renderer;

      // 立方体ジオメトリ & マテリアル
      const geometry = new THREE.BoxGeometry(1.8, 1.8, 1.8);
      const material = new THREE.MeshStandardMaterial({
        color: configRef.current.color,
        wireframe: configRef.current.wireframe,
        metalness: configRef.current.metallic ? 0.85 : 0.1,
        roughness: configRef.current.metallic ? 0.2 : 0.65,
      });
      materialRef.current = material;

      const cube = new THREE.Mesh(geometry, material);
      cube.castShadow = true;
      cube.receiveShadow = true;
      scene.add(cube);
      cubeMeshRef.current = cube;

      // エッジライン
      const edgesGeometry = new THREE.EdgesGeometry(geometry);
      const edgesMaterial = new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.15,
      });
      const edgeLines = new THREE.LineSegments(edgesGeometry, edgesMaterial);
      cube.add(edgeLines);

      // 下部グリッド床面
      const gridHelper = new THREE.GridHelper(10, 20, 0x38bdf8, 0x1e293b);
      gridHelper.position.y = -1.6;
      scene.add(gridHelper);

      // ライト設定
      const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
      scene.add(ambientLight);

      const dirLight1 = new THREE.DirectionalLight(0xffffff, 1.2);
      dirLight1.position.set(5, 8, 5);
      dirLight1.castShadow = true;
      dirLight1.shadow.mapSize.width = 1024;
      dirLight1.shadow.mapSize.height = 1024;
      scene.add(dirLight1);

      const dirLight2 = new THREE.DirectionalLight(0x38bdf8, 0.6);
      dirLight2.position.set(-5, -4, -5);
      scene.add(dirLight2);

      // アニメーションループ
      const clock = new THREE.Clock();

      const animate = () => {
        reqIdRef.current = requestAnimationFrame(animate);
        const delta = clock.getDelta();

        if (configRef.current.autoRotate && cubeMeshRef.current) {
          cubeMeshRef.current.rotation.y += delta * configRef.current.rotateSpeed;
          cubeMeshRef.current.rotation.x += delta * (configRef.current.rotateSpeed * 0.4);
        }

        renderer.render(scene, camera);
      };

      animate();

      // ポインター操作（マウスドラッグ ＆ 2本指ピンチズーム対応）
      const onPointerDown = (e: PointerEvent) => {
        activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
        canvas.setPointerCapture?.(e.pointerId);

        if (activePointersRef.current.size === 1) {
          isDraggingRef.current = true;
          previousPointerPositionRef.current = { x: e.clientX, y: e.clientY };
        } else if (activePointersRef.current.size === 2) {
          isDraggingRef.current = false;
          const points = Array.from(activePointersRef.current.values());
          const dist = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
          initialPinchDistanceRef.current = dist;
          initialCameraDistanceRef.current = cameraDistanceRef.current;
        }
      };

      const onPointerMove = (e: PointerEvent) => {
        if (!activePointersRef.current.has(e.pointerId)) return;
        activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

        // 2本指でのピンチズーム
        if (activePointersRef.current.size === 2 && initialPinchDistanceRef.current !== null) {
          const points = Array.from(activePointersRef.current.values());
          const currentDist = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
          if (currentDist > 0) {
            const ratio = initialPinchDistanceRef.current / currentDist;
            const newDistance = initialCameraDistanceRef.current * ratio;
            cameraDistanceRef.current = Math.max(2.5, Math.min(12, newDistance));
            updateCameraPosition();
          }
          return;
        }

        // 1本指またはマウスクリックでの視点回転
        if (isDraggingRef.current && activePointersRef.current.size === 1) {
          const deltaX = e.clientX - previousPointerPositionRef.current.x;
          const deltaY = e.clientY - previousPointerPositionRef.current.y;

          const sensitivity = 0.007;
          rotationAnglesRef.current.y -= deltaX * sensitivity;
          rotationAnglesRef.current.x = Math.max(
            -Math.PI / 2 + 0.05,
            Math.min(Math.PI / 2 - 0.05, rotationAnglesRef.current.x + deltaY * sensitivity)
          );

          previousPointerPositionRef.current = { x: e.clientX, y: e.clientY };
          updateCameraPosition();
        }
      };

      const onPointerUp = (e: PointerEvent) => {
        activePointersRef.current.delete(e.pointerId);
        try {
          canvas.releasePointerCapture?.(e.pointerId);
        } catch {
          // 解除不可時は無視
        }

        if (activePointersRef.current.size === 1) {
          const remainingPoint = Array.from(activePointersRef.current.values())[0];
          previousPointerPositionRef.current = { x: remainingPoint.x, y: remainingPoint.y };
          isDraggingRef.current = true;
          initialPinchDistanceRef.current = null;
        } else if (activePointersRef.current.size === 0) {
          isDraggingRef.current = false;
          initialPinchDistanceRef.current = null;
        }
      };

      // マウスホイールによるズーム
      const onWheel = (e: WheelEvent) => {
        e.preventDefault();
        const zoomFactor = e.deltaY * 0.003;
        cameraDistanceRef.current = Math.max(2.5, Math.min(12, cameraDistanceRef.current + zoomFactor));
        updateCameraPosition();
      };

      canvas.addEventListener('pointerdown', onPointerDown);
      canvas.addEventListener('pointermove', onPointerMove);
      canvas.addEventListener('pointerup', onPointerUp);
      canvas.addEventListener('pointercancel', onPointerUp);
      canvas.addEventListener('wheel', onWheel, { passive: false });

      // リサイズ監視
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const newWidth = entry.contentRect.width;
          const newHeight = entry.contentRect.height;
          if (newWidth > 0 && newHeight > 0 && cameraRef.current && rendererRef.current) {
            cameraRef.current.aspect = newWidth / newHeight;
            cameraRef.current.updateProjectionMatrix();
            rendererRef.current.setSize(newWidth, newHeight);
          }
        }
      });

      resizeObserver.observe(container);

      // クリーンアップ処理
      return () => {
        if (reqIdRef.current) {
          cancelAnimationFrame(reqIdRef.current);
        }
        resizeObserver.disconnect();
        canvas.removeEventListener('pointerdown', onPointerDown);
        canvas.removeEventListener('pointermove', onPointerMove);
        canvas.removeEventListener('pointerup', onPointerUp);
        canvas.removeEventListener('pointercancel', onPointerUp);
        canvas.removeEventListener('wheel', onWheel);

        // シーン内の全ジオメトリ・マテリアル・テクスチャ・ライトを包括的に解放
        scene.traverse((object) => {
          if (object instanceof THREE.Mesh || object instanceof THREE.LineSegments) {
            if (object.geometry) {
              object.geometry.dispose();
            }
            if (object.material) {
              if (Array.isArray(object.material)) {
                object.material.forEach((mat) => mat.dispose());
              } else {
                object.material.dispose();
              }
            }
          }
          if (object instanceof THREE.Light && 'dispose' in object && typeof (object as { dispose?: () => void }).dispose === 'function') {
            (object as { dispose: () => void }).dispose();
          }
        });
        scene.clear();

        renderer.dispose();
      };
    }, [updateCameraPosition]);

    return (
      <div className="canvas-wrapper" ref={mountRef}>
        <canvas className="three-canvas" ref={canvasRef} />
      </div>
    );
  }
);

ThreeCanvas.displayName = 'ThreeCanvas';

export default ThreeCanvas;

import React from 'react';
import { RotateCcw } from 'lucide-react';
import { ControlPanelProps } from '../types';

const PRESET_COLORS = [
  '#38bdf8', // スカイブルー
  '#ec4899', // ネオンピンク
  '#10b981', // エメラルドグリーン
  '#f59e0b', // アンバーゴールド
  '#8b5cf6', // バイオレットパープル
  '#ef4444', // ルビーレッド
];

const ControlPanel = ({ config, onChangeConfig, onResetView }: ControlPanelProps) => {
  const handleColorSelect = (color: string) => {
    onChangeConfig({ color });
  };

  const handleToggleMaterial = () => {
    onChangeConfig({ metallic: !config.metallic });
  };

  const handleToggleWireframe = () => {
    onChangeConfig({ wireframe: !config.wireframe });
  };

  const handleToggleAutoRotate = () => {
    onChangeConfig({ autoRotate: !config.autoRotate });
  };

  const handleSpeedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ rotateSpeed: parseFloat(e.target.value) });
  };

  return (
    <aside className="control-panel">
      {/* カラー選択セクション */}
      <div className="panel-section">
        <h3 className="section-title">カラープリセット</h3>
        <div className="color-palette" role="group" aria-label="プリセットカラー選択">
          {PRESET_COLORS.map((hex) => {
            const isActive = config.color.toLowerCase() === hex.toLowerCase();
            return (
              <button
                key={hex}
                type="button"
                className={`color-btn ${isActive ? 'color-btn-active' : ''}`}
                style={{ backgroundColor: hex }}
                onClick={() => handleColorSelect(hex)}
                aria-label={`カラー変更: ${hex}`}
                aria-pressed={isActive}
              />
            );
          })}
        </div>

        {/* カスタムカラー指定 */}
        <div className="control-row" style={{ marginTop: '0.5rem' }}>
          <label htmlFor="customColorPicker" className="control-label">
            カスタムカラー
          </label>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
            <input
              id="customColorPicker"
              type="color"
              value={config.color}
              onChange={(e) => handleColorSelect(e.target.value)}
              aria-label="カスタムカラーピッカー"
              style={{
                width: '32px',
                height: '32px',
                padding: '0',
                border: '1px solid var(--border-color)',
                borderRadius: 'var(--radius-sm)',
                background: 'none',
                cursor: 'pointer',
