          <span className="control-label">質感スタイル</span>
          <button
            type="button"
            className={`toggle-btn ${config.metallic ? 'toggle-btn-active' : ''}`}
            onClick={handleToggleMaterial}
            aria-pressed={config.metallic}
          >
            {config.metallic ? '光沢メタリック' : 'マット'}
