        </div>

        <div className="control-row">
          <span className="control-label">ワイヤーフレーム</span>
          <button
            type="button"
            className={`toggle-btn ${config.wireframe ? 'toggle-btn-active' : ''}`}
            onClick={handleToggleWireframe}
            aria-pressed={config.wireframe}
          >
            {config.wireframe ? '有効' : '無効'}
          </button>
        </div>
      </div>

      {/* アニメーション制御セクション */}
      <div className="panel-section">
        <h3 className="section-title">アニメーション</h3>

        <div className="control-row">
