            onChange={handleSpeedChange}
            className="range-slider"
            aria-label="回転速度"
          />
          <span className="range-value">{config.rotateSpeed.toFixed(1)}x</span>
        </div>
      </div>

      {/* 視点リセットボタン */}
      <button type="button" className="reset-btn" onClick={onResetView}>
        <RotateCcw size={16} />
        視点をリセット
      </button>
    </aside>
  );
};

export default ControlPanel;

import { useState, useRef, useCallback, useEffect } from 'react';
import { Box, MousePointer, Keyboard } from 'lucide-react';
import ThreeCanvas, { ThreeCanvasHandle } from './components/ThreeCanvas';
import ControlPanel from './components/ControlPanel';
import { CubeConfig } from './types';

const INITIAL_CONFIG: CubeConfig = {
  color: '#38bdf8',
  wireframe: false,
  autoRotate: true,
  rotateSpeed: 1.0,
  metallic: true,
};

const App = () => {
  const [config, setConfig] = useState<CubeConfig>(INITIAL_CONFIG);
  const canvasRef = useRef<ThreeCanvasHandle | null>(null);

  const handleConfigChange = useCallback((newConfig: Partial<CubeConfig>) => {
    setConfig((prev) => ({
      ...prev,
      ...newConfig,
    }));
  }, []);

  const handleResetView = useCallback(() => {
    canvasRef.current?.resetView();
  }, []);

  // キーボードショートカット（Space: 自動回転ON/OFF, R: 視点リセット）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // 入力フォーム操作時はショートカットを抑制
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement ||
        e.target instanceof HTMLSelectElement
      ) {
        return;
      }

      if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        handleResetView();
      } else if (e.key === ' ' || e.code === 'Space') {
        e.preventDefault();
        setConfig((prev) => ({
          ...prev,
          autoRotate: !prev.autoRotate,
        }));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleResetView]);

  return (
    <div className="app-container">
      {/* アプリケーションヘッダー */}
      <header className="app-header">
        <h1 className="header-title">
          <Box size={24} color="#38bdf8" />
          3D キューブ ビューワー
        </h1>
        <p className="header-subtitle">
          Three.jsを活用した高機能リアルタイム3Dマテリアル＆アニメーションシミュレーター
        </p>
      </header>

      {/* メインレイアウト */}
      <main className="main-layout">
        {/* 3Dキャンバス領域 */}
        <div className="canvas-container">
          <ThreeCanvas ref={canvasRef} config={config} />

          {/* 操作ヘルプヒント */}
          <div className="hint-box">
            <span className="hint-icon">
              <MousePointer size={16} />
            </span>
            <span className="hint-text">
              ドラッグで全方向回転 / ホイールでズーム拡大縮小
            </span>
            <span className="hint-icon" style={{ marginLeft: '0.5rem' }}>
              <Keyboard size={16} />
            </span>
            <span className="hint-text">
              <span className="kbd-badge">Space</span> 回転切替 / <span className="kbd-badge">R</span> リセット
            </span>
          </div>
        </div>

        {/* コントロールパネル */}
        <ControlPanel
          config={config}
          onChangeConfig={handleConfigChange}
          onResetView={handleResetView}
        />
      </main>
    </div>
  );
};

export default App;
